import { describe, expect, it } from "vitest";
import { ALL_TOOL_CONTRACTS, generateLabelEvidence, generateTraceAssertions, generateVerdictEvidence, getGraderLabels, getGraderVerdicts, getTraceLabels, getTraceVerdicts, installToolParameterWarnings, saveAgentLabels, saveAgentVerdicts, saveGraderLabels, saveGraderVerdicts, saveHumanLabels, saveHumanVerdicts, saveScenario, saveTraceAssertions, searchTraces, TOOL_NAMES, toolConfig, } from "./mcpContract.js";
const TRACE_ID = "00000000-0000-4000-8000-000000000001";
const ASSERTION_ID = "00000000-0000-4000-8000-000000000002";
const GRADER_ID = "00000000-0000-4000-8000-000000000003";
describe("tool contracts", () => {
    it("registers 68 tools with unique names", () => {
        expect(ALL_TOOL_CONTRACTS).toHaveLength(68);
        expect(new Set(TOOL_NAMES).size).toBe(68);
        expect(TOOL_NAMES).toContain("list_organization_members");
        expect(TOOL_NAMES).toContain("get_span");
        expect(TOOL_NAMES).toContain("save_grader_verdicts");
        expect(TOOL_NAMES).toContain("save_grader_labels");
        expect(TOOL_NAMES.join(" ")).not.toMatch(/trace_plan/);
        expect(TOOL_NAMES).not.toContain("create_trace_plan");
        expect(TOOL_NAMES).not.toContain("update_trace_plan");
    });
    it("names every tool in snake_case", () => {
        for (const contract of ALL_TOOL_CONTRACTS) {
            expect(contract.name, contract.name).toMatch(/^[a-z][a-z0-9]*(_[a-z0-9]+)*$/);
        }
    });
    it("gives every tool a title and a description", () => {
        for (const contract of ALL_TOOL_CONTRACTS) {
            expect(contract.title.length, contract.name).toBeGreaterThan(0);
            expect(contract.description.length, contract.name).toBeGreaterThan(0);
        }
    });
    it("names every input parameter in camelCase", () => {
        for (const contract of ALL_TOOL_CONTRACTS) {
            for (const param of Object.keys(contract.inputSchema)) {
                expect(param, `${contract.name}.${param}`).toMatch(/^[a-z][a-zA-Z0-9]*$/);
            }
        }
    });
    it("describes every input parameter", () => {
        for (const contract of ALL_TOOL_CONTRACTS) {
            for (const [param, schema] of Object.entries(contract.inputSchema)) {
                expect(schema.description, `${contract.name}.${param} has no .describe()`).toBeTruthy();
            }
        }
    });
    it("drops the name from the registerTool config", () => {
        const config = toolConfig(ALL_TOOL_CONTRACTS[0]);
        expect(config).not.toHaveProperty("name");
        expect(Object.keys(config).sort()).toEqual([
            "description",
            "inputSchema",
            "title",
        ]);
    });
    it("marks unsupported parameters invalid before the warning wrapper runs", () => {
        for (const contract of ALL_TOOL_CONTRACTS) {
            const result = toolConfig(contract).inputSchema.safeParse({
                unsupportedFutureParameter: true,
            });
            expect(result.success, contract.name).toBe(false);
            if (!result.success) {
                expect(result.error.issues.some((issue) => issue.code === "unrecognized_keys"), contract.name).toBe(true);
            }
        }
    });
    it("warns and preserves successful behavior for supported parameters", async () => {
        let receivedRequest;
        const protocolServer = {
            _requestHandlers: new Map(),
        };
        protocolServer._requestHandlers.set("tools/call", async (request) => {
            receivedRequest = request;
            return { content: [{ type: "text", text: "success" }] };
        });
        installToolParameterWarnings(protocolServer, [searchTraces], "Bitfab plugin 1.2.3");
        const handler = protocolServer._requestHandlers.get("tools/call");
        const result = (await handler?.({
            method: "tools/call",
            params: {
                name: "search_traces",
                arguments: {
                    traceFunctionKey: "checkout",
                    unsupportedFutureParameter: true,
                },
            },
        }, {}));
        expect(receivedRequest).toEqual({
            method: "tools/call",
            params: {
                name: "search_traces",
                arguments: { traceFunctionKey: "checkout" },
            },
        });
        expect(result.isError).toBeUndefined();
        expect(result.content).toEqual([
            { type: "text", text: "success" },
            {
                type: "text",
                text: "Warning: Bitfab plugin 1.2.3 ignored unsupported parameter for search_traces: unsupportedFutureParameter. Update Bitfab if you expected it to take effect.",
            },
        ]);
    });
    it("lets MCP callers write people-only notes on assertions", () => {
        const parsed = saveTraceAssertions.inputSchema.assertions.safeParse([
            {
                assertion: "The itinerary lands before 9am",
                humanNote: "Preserve this for the human reviewer",
            },
        ]);
        expect(parsed.success).toBe(true);
        expect(saveTraceAssertions.description).toMatch(/never use it to judge/);
    });
    it("describes assertion generation as the model-backed trigger and parses regeneration", () => {
        const parsed = generateTraceAssertions.inputSchema.regenerate.safeParse("true");
        expect(parsed).toEqual({ success: true, data: true });
        expect(generateTraceAssertions.description).toContain("Call this when the user asks Bitfab to generate assertions");
        expect(generateTraceAssertions.description).toContain("saved awaiting human review");
    });
    it("takes generation categories as a list or as the JSON string a stringly-typed client sends", () => {
        const categoryId = crypto.randomUUID();
        const schema = generateTraceAssertions.inputSchema.categoryIds;
        expect(schema.safeParse([categoryId])).toEqual({
            success: true,
            data: [categoryId],
        });
        expect(schema.safeParse(JSON.stringify([categoryId]))).toEqual({
            success: true,
            data: [categoryId],
        });
        expect(schema.safeParse([]).success).toBe(false);
        expect(generateTraceAssertions.inputSchema.guidance.safeParse("  ").success).toBe(false);
    });
    it("takes a justification as objects or as the JSON string a stringly-typed client sends", () => {
        const justification = [{ spanId: crypto.randomUUID(), text: "Lands 08:40" }];
        const entry = {
            assertion: "The itinerary lands before 9am",
            justification,
            categoryJustification: justification,
        };
        const native = saveTraceAssertions.inputSchema.assertions.safeParse([entry]);
        const stringified = saveTraceAssertions.inputSchema.assertions.safeParse(JSON.stringify([entry]));
        expect(native.success).toBe(true);
        expect(stringified.success).toBe(true);
        expect(stringified.data?.[0].justification).toEqual(justification);
    });
    it("refuses a justification with no cited span, blank text, or a non-uuid span", () => {
        const parse = (justification) => saveTraceAssertions.inputSchema.assertions.safeParse([
            { assertion: "Lands before 9am", justification },
        ]).success;
        expect(parse([])).toBe(false);
        expect(parse([{ spanId: crypto.randomUUID(), text: "   " }])).toBe(false);
        expect(parse([{ spanId: "not-a-uuid", text: "Lands 08:40" }])).toBe(false);
        expect(parse([{ text: "Missing the span" }])).toBe(false);
    });
    it("takes an actual outcome with typed actions, as objects or as a JSON string", () => {
        const schema = saveScenario.inputSchema.actualOutcome;
        const outcome = {
            summary: "Sent Ryan three tapas bars.",
            actions: [
                {
                    name: "send_sms_message",
                    details: { message: "Casa Labra" },
                    result: "queued",
                    failed: false,
                    at: null,
                },
            ],
            source: {
                spanId: crypto.randomUUID(),
                sourceField: "output",
                text: "Sent Ryan three tapas bars.",
            },
        };
        expect(schema.safeParse(outcome)).toEqual({ success: true, data: outcome });
        expect(schema.safeParse(JSON.stringify(outcome))).toEqual({
            success: true,
            data: outcome,
        });
        expect(schema.safeParse(null)).toEqual({ success: true, data: null });
    });
    it("refuses an actual outcome action that is missing a field or has an unknown one", () => {
        const parse = (action) => saveScenario.inputSchema.actualOutcome.safeParse({
            summary: "Sent a text.",
            actions: [action],
        }).success;
        const action = {
            name: "send_sms_message",
            details: {},
            result: null,
            failed: false,
            at: null,
        };
        expect(parse(action)).toBe(true);
        expect(parse({ ...action, name: "" })).toBe(false);
        expect(parse({ ...action, failed: undefined })).toBe(false);
        expect(parse({ ...action, tool: "send_sms_message" })).toBe(false);
        expect(saveScenario.inputSchema.actualOutcome.safeParse({
            summary: "Sent a text.",
            actions: [],
            source: { spanId: "not-a-uuid", sourceField: "output", text: "x" },
        }).success).toBe(false);
    });
    it("normalizes caller metadata filters for case-insensitive search", () => {
        expect(searchTraces.inputSchema.callerMetadata.parse({ Ticket_ID: "ABC-123" })).toEqual({ ticket_id: "abc-123" });
    });
    it("normalizes name filters for case-insensitive search", () => {
        expect(searchTraces.inputSchema.name.parse("  Nightly Checkout ")).toBe("nightly checkout");
        expect(searchTraces.inputSchema.nameContains.parse(" CHECKOUT ")).toBe("checkout");
    });
    it("refuses a name substring too short to use the trigram index", () => {
        expect(searchTraces.inputSchema.nameContains.safeParse("ab").success).toBe(false);
    });
    it.each([
        [
            getTraceLabels,
            getTraceVerdicts,
            "get_trace_labels",
            "get_trace_verdicts",
        ],
        [
            generateLabelEvidence,
            generateVerdictEvidence,
            "generate_label_evidence",
            "generate_verdict_evidence",
        ],
        [
            saveAgentLabels,
            saveAgentVerdicts,
            "save_agent_labels",
            "save_agent_verdicts",
        ],
        [
            saveHumanLabels,
            saveHumanVerdicts,
            "save_human_labels",
            "save_human_verdicts",
        ],
        [
            getGraderLabels,
            getGraderVerdicts,
            "get_grader_labels",
            "get_grader_verdicts",
        ],
        [
            saveGraderLabels,
            saveGraderVerdicts,
            "save_grader_labels",
            "save_grader_verdicts",
        ],
    ])("keeps %s as a deprecated alias that takes the same arguments", (alias, current, oldName, newName) => {
        expect(current.name).toBe(newName);
        expect(alias.name).toBe(oldName);
        expect(alias.inputSchema).toBe(current.inputSchema);
        expect(alias.description).toBe(`Deprecated: use ${newName}, which does the same thing. ${current.description}`);
        expect(TOOL_NAMES).toContain(oldName);
        expect(TOOL_NAMES).toContain(newName);
    });
    it("takes verdicts as pass, fail, or abstained, and keeps the old labels spelling", () => {
        const entry = {
            traceId: TRACE_ID,
            assertionId: ASSERTION_ID,
            annotation: "why",
        };
        const schema = toolConfig(saveAgentVerdicts).inputSchema;
        for (const verdict of ["pass", "fail", "abstained"]) {
            expect(schema.safeParse({ verdicts: [{ ...entry, verdict }] }).success, verdict).toBe(true);
        }
        expect(schema.safeParse({ verdicts: [{ ...entry, verdict: "maybe" }] }).success).toBe(false);
        expect(schema.safeParse({ labels: [{ ...entry, label: true }] }).success).toBe(true);
        expect(schema.safeParse({ labels: [{ ...entry, abstain: true }] }).success).toBe(true);
    });
    it("refuses an abstention from a person or an external grader", () => {
        expect(toolConfig(saveHumanVerdicts).inputSchema.safeParse({
            verdicts: [
                {
                    traceId: TRACE_ID,
                    assertionId: ASSERTION_ID,
                    verdict: "abstained",
                    annotation: "why",
                },
            ],
        }).success).toBe(false);
        expect(toolConfig(saveGraderVerdicts).inputSchema.safeParse({
            verdicts: [
                { graderId: GRADER_ID, traceId: TRACE_ID, verdict: "abstained" },
            ],
        }).success).toBe(false);
        expect(toolConfig(saveGraderVerdicts).inputSchema.safeParse({
            verdicts: [{ graderId: GRADER_ID, traceId: TRACE_ID, verdict: "pass" }],
        }).success).toBe(true);
    });
    it("marks the old spellings deprecated in the advertised schema", () => {
        const deprecated = (schema) => schema.meta()
            ?.deprecated;
        expect(deprecated(saveAgentVerdicts.inputSchema.labels)).toBe(true);
        expect(deprecated(saveHumanVerdicts.inputSchema.labels)).toBe(true);
        expect(deprecated(saveGraderVerdicts.inputSchema.labels)).toBe(true);
        expect(deprecated(searchTraces.inputSchema.labelSource)).toBe(true);
        expect(deprecated(searchTraces.inputSchema.labelResult)).toBe(true);
        expect(deprecated(searchTraces.inputSchema.verdictSource)).toBeUndefined();
        expect(deprecated(searchTraces.inputSchema.verdictResult)).toBeUndefined();
    });
});
